t.script:
(function () {
    var expiresIn = ;
    var resendIn = ;

    var countdownEl = document.getElementById("otp_countdown");
    var expiryBadge = document.getElementById("otp_expiry_badge");
    var submitBtn = document.getElementById("otp_submit_btn");
    var resendBtn = document.getElementById("otp_resend_btn");
    var resendLabel = resendBtn.textContent.trim();

    function formatTime(totalSeconds) {
        var m = Math.floor(totalSeconds / 60);
        var s = totalSeconds % 60;
        return (m < 5 ? "0" : "") + m + ":" + (s < 5 ? "0" : "") + s;
    }

    var expiryTimer = setInterval(function () {
        expiresIn -= 1;
        if (expiresIn <= 0) {
            clearInterval(expiryTimer);
            countdownEl.textContent = "expired";
            expiryBadge.classList.add("o_otp_expiry--expired");
            submitBtn.disabled = true;
            return;
        }
        countdownEl.textContent = formatTime(expiresIn);
    }, 1000);
    countdownEl.textContent = expiresIn > 0 ? formatTime(expiresIn) : "expired";
    if (expiresIn <= 0) {
        expiryBadge.classList.add("o_otp_expiry--expired");
        submitBtn.disabled = true;
    }

    var resendTimer = setInterval(function () {
        resendIn -= 1;
        if (resendIn <= 0) {
            clearInterval(resendTimer);
            resendBtn.disabled = false;
            resendBtn.textContent = resendLabel;
            return;
        }
        resendBtn.textContent = resendLabel + " (" + resendIn + "s)";
    }, 1000);
    if (resendIn > 0) {
        resendBtn.textContent = resendLabel + " (" + resendIn + "s)";
    } else {
        resendBtn.disabled = false;
    }

    // --- 6-box code input, kept in sync with the hidden field ---
    var boxes = Array.prototype.slice.call(
        document.querySelectorAll(".o_otp_digits input")
    );
    var hidden = document.getElementById("otp_code_hidden");
    var form = document.getElementById("otp_verify_form");

    function syncHidden() {
        hidden.value = boxes.map(function (b) { return b.value; }).join("");
    }

    boxes.forEach(function (box, i) {
        box.addEventListener("input", function () {
            box.value = box.value.replace(/[^0-9]/g, "").slice(0, 1);
            box.classList.remove("is-invalid");
            if (box.value && boxes[i + 1]) {
                boxes[i + 1].focus();
            }
            syncHidden();
        });

        box.addEventListener("keydown", function (ev) {
            if (ev.key === "Backspace" && !box.value && boxes[i - 1]) {
                boxes[i - 1].focus();
            }
        });

        box.addEventListener("paste", function (ev) {
            var text = (ev.clipboardData || window.clipboardData)
                .getData("text").replace(/[^0-9]/g, "");
            if (!text) {
                return;
            }
            ev.preventDefault();
            text.slice(0, boxes.length).split("").forEach(function (ch, j) {
                if (boxes[i + j]) {
                    boxes[i + j].value = ch;
                }
            });
            var next = boxes[Math.min(i + text.length, boxes.length - 1)];
            next.focus();
            syncHidden();
        });
    });

    form.addEventListener("submit", function () {
        syncHidden();
        if (hidden.value.length < boxes.length) {
            boxes.forEach(function (b) { b.classList.add("is-invalid"); });
        }
    });

    if (boxes[0]) {
        boxes[0].focus();
    }
})();
